ga1z(){return"\u0627\u0644\u0639\u0645\u0644\u0627\u0621"},
ga1F(){return"\u0627\u0644\u0645\u0648\u0631\u062f\u0648\u0646"},
ga1A(){return"\u0643\u0644 \u0645\u0627 \u064a\u0645\u0644\u0643\u0647 \u0627\u0644\u0633\u062c\u0644 \u0627\u0644\u0645\u0643\u0631\u0631 \u2014 \u0627\u0644\u0641\u0648\u0627\u062a\u064a\u0631 \u0648\u0642\u064a\u0648\u062f \u062f\u0641\u062a\u0631 \u0627\u0644\u0623\u0633\u062a\u0627\u0630 \u0648\u0627\u0644\u062a\u0648\u0635\u064a\u0644\u0627\u062a \u0648\u0627\u0644\u0645\u0634\u062a\u0631\u064a\u0627\u062a\u060c \u0623\u064a\u064b\u0627 \u0643\u0627\u0646 \u0645\u0627 \u064a\u0646\u0637\u0628\u0642 \u2014 \u064a\u0646\u062a\u0642\u0644 \u0625\u0644\u0649 \u0627\u0644\u0633\u062c\u0644 \u0627\u0644\u0630\u064a \u062a\u062d\u062a\u0641\u0638 \u0628\u0647. \u062b\u0645 \u062a\u062a\u0645 \u0625\u0632\u0627\u0644\u0629 \u0627\u0644\u0633\u062c\u0644 \u0627\u0644\u0645\u0643\u0631\u0631 \u0646\u0641\u0633\u0647. \u0644\u0627 \u064a\u0645\u0643\u0646 \u0627\u0644\u062a\u0631\u0627\u062c\u0639 \u0639\u0646 \u0647\u0630\u0627."},
