gMp(){return"\u0646\u0641\u0633 \u0631\u0642\u0645 \u0627\u0644\u0647\u0627\u062a\u0641 \u0645\u0633\u062c\u0644"},
gMo(){return"\u0646\u0641\u0633 \u0627\u0644\u0627\u0633\u0645 \u0645\u0633\u062c\u0644"},
