gPq(){return"\u0627\u0644\u0641\u0631\u0648\u0639 \u0648\u0627\u0644\u0645\u0633\u062a\u0648\u062f\u0639\u0627\u062a"},
gPs(){return"\u0645\u0648\u0642\u0639 \u0648\u0627\u062d\u062f \u2014 \u0623\u0636\u0641 \u0641\u0631\u0639\u064b\u0627 \u0647\u0646\u0627 \u0644\u0641\u062a\u062d \u0648\u0636\u0639 \u062a\u0639\u062f\u062f \u0627\u0644\u0641\u0631\u0648\u0639"},
