gVh(){return"\u0627\u0644\u0639\u0646\u0648\u0627\u0646 \u2014 \u064a\u064f\u0637\u0628\u0639 \u0639\u0644\u0649 \u0643\u0644 \u0641\u0627\u062a\u0648\u0631\u0629"},
gVg(){return"\u0627\u0645\u0644\u0623 \u0647\u0630\u0627 \u0645\u0631\u0629 \u0648\u0627\u062d\u062f\u0629 \u2014 \u064a\u064f\u0637\u0628\u0639 \u0639\u0644\u0649 \u0643\u0644 \u0641\u0627\u062a\u0648\u0631\u0629 \u062a\u0645\u0627\u0645\u064b\u0627 \u0645\u062b\u0644 \u0627\u0644\u0646\u0645\u0648\u0630\u062c (\u0634\u062e\u0635 \u0627\u0644\u0627\u062a\u0635\u0627\u0644\u060c \u0627\u0644\u0645\u0628\u0646\u0649/\u0627\u0644\u0634\u0627\u0631\u0639/\u0627\u0644\u0645\u0646\u0637\u0642\u0629\u060c \u0635\u0646\u062f\u0648\u0642 \u0627\u0644\u0628\u0631\u064a\u062f\u060c \u0627\u0644\u0645\u062f\u064a\u0646\u0629\u060c \u0627\u0644\u062f\u0648\u0644\u0629)."},
gVn(){return"\u0627\u0644\u0639\u0645\u0644\u0629 \u0627\u0644\u0623\u0633\u0627\u0633\u064a\u0629"},
gVl(){return"\u0643\u0644 \u062a\u0642\u0631\u064a\u0631 \u0648\u0639\u0645\u064a\u0644/\u0641\u0627\u062a\u0648\u0631\u0629 \u062c\u062f\u064a\u062f\u0629 \u064a\u0641\u062a\u0631\u0636 \u0647\u0630\u0627 \u0627\u0641\u062a\u0631\u0627\u0636\u064a\u064b\u0627. \u062a\u063a\u064a\u064a\u0631\u0647 \u0644\u0627 \u064a\u062d\u0648\u0644 \u0627\u0644\u0623\u0631\u0642\u0627\u0645 \u0627\u0644\u062a\u0627\u0631\u064a\u062e\u064a\u0629 \u0628\u0623\u062b\u0631 \u0631\u062c\u0639\u064a \u2014 \u062a\u0628\u0642\u0649 \u0628\u0627\u0644\u0639\u0645\u0644\u0629 \u0627\u0644\u062a\u064a \u0631\u064f\u062d\u0651\u0644\u062a \u0628\u0647\u0627."},
