ga30(){return'\u091c\u0948\u0938\u0947 "\u092b\u094d\u0930\u0902\u091f \u0921\u0947\u0938\u094d\u0915 \u092b\u094d\u0932\u094b\u091f"'},
ga2Y(){return"\u0905\u092d\u093f\u0930\u0915\u094d\u0937\u0915 (\u0935\u0948\u0915\u0932\u094d\u092a\u093f\u0915)"},
ga36(){return"\u092a\u094d\u0930\u093e\u0930\u0902\u092d\u093f\u0915 \u092b\u094d\u0932\u094b\u091f"},
gMK(){return"\u0930\u093e\u0936\u093f"},
ga2V(){return"\u0936\u094d\u0930\u0947\u0923\u0940"},
ga35(){return"\u0928\u094b\u091f (\u0935\u0948\u0915\u0932\u094d\u092a\u093f\u0915)"},
